import RNA, random, sys
target='.((.((.((..((.(...).)).))..))....)).'
n=len(target)
stack=[]; pairs=[]
for i,c in enumerate(target):
    if c=='(' : stack.append(i)
    elif c==')': pairs.append((stack.pop(),i))
pairs=sorted(pairs)
pairset=set()
for i,j in pairs: pairset.add(i); pairset.add(j)

complements={'G':['C'],'C':['G'],'A':['U'],'U':['A'],'G':['C','U'],'U':['A','G']}
# valid Watson-Crick & wobble pairs
wc={'GC','CG','AU','UA','GU','UG'}

def fold(s):
    return RNA.fold_compound(s).mfe()[0]

def score(s):
    ss=fold(s)
    if ss==target: return -1000
    return sum(1 for a,b in zip(ss,target) if a!=b)

best_global=None; best_d=999
random.seed(7)
for restart in range(50):
    # build respecting pairs: pick a pairing for each stem
    seq=['A']*n
    # fill loops with random unpaired-ish (A/U) to avoid spurious
    for idx,(i,j) in enumerate(pairs):
        a=random.choice('GCAU'); b=RNA.complement(a) if a in 'GCA' else 'C'
        # ensure WC
        if a=='G': b='C'
        elif a=='C': b='G'
        elif a=='A': b='U'
        elif a=='U': b='A'
        # wobble sometimes
        if random.random()<0.1:
            if a=='G': b='U'
            if a=='U': b='G'
        seq[i]=a; seq[j]=b
    # loops
    for pos in range(n):
        if pos not in pairset:
            seq[pos]=random.choice('AU')
    cur=''.join(seq)
    cs=score(cur)
    # local hill climb respecting pair constraints
    improved=True
    while improved:
        improved=False
        # try mutate each pair's base pairing choice + loop positions
        for (i,j) in pairs:
            for a,b in [('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')]:
                cand=list(cur)
                cand[i]=a; cand[j]=b
                cs2=score(''.join(cand))
                if cs2<cs:
                    cur=''.join(cand); cs=cs2; improved=True
        for pos in range(n):
            if pos in pairset: continue
            for a in 'ACGU':
                cand=list(cur); cand[pos]=a
                cs2=score(''.join(cand))
                if cs2<cs:
                    cur=''.join(cand); cs=cs2; improved=True
    if cs<best_d:
        best_d=cs; best_global=cur
        print('restart',restart,'best_d',best_d,cur,file=sys.stderr)
    if best_d<=-1000:
        print('SOLVED',best_global); sys.exit(0)
print('BEST',best_global,'d',best_d, file=sys.stderr)
print(best_global)
EOF
